def solve(s: str) -> int:
    """Return length of longest substring without repeating characters.
    Sliding window using a dict of last seen positions.
    """
    last = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        # update max_len
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
        last[ch] = i
    return max_len

